    document.querySelector('[data-new-summary]').innerHTML = `<b>${rows.length}</b> itens · subtotal ${money(total)} · valor rateado ${money(rateado)} · não rateado ${money(total - rateado)} · ${oss.size} OS(s) atendidas`;
