    bd.addEventListener('click', (e) => { if (e.target.matches('[data-add-new-row]')) { e.target.previousElementSibling.insertAdjacentHTML('beforeend', newItemRow(document.querySelectorAll('.item-form-row').length + 1)); updateNewSummary(); } if (e.target.matches('[data-remove-row]')) { e.target.closest('.item-form-row').remove(); updateNewSummary(); } if (e.target.matches('[data-dup-row]')) { e.target.closest('.item-form-row').insertAdjacentHTML('afterend', e.target.closest('.item-form-row').outerHTML); updateNewSummary(); } });
